function applyNavigationOrder(){let order=navigationOrder(),nav=document.querySelector('.sidebar nav');if(!nav)return;nav.classList.remove('custom-nav-order');nav.querySelectorAll('.nav').forEach(button=>button.style.removeProperty('order'));let groups=[{title:'',pages:['dashboard','today','finance']},{title:'ORGANIZAÇÃO',pages:['tasks','habits','calendar','goals']},{title:'BEM-ESTAR',pages:['focus','mood','notes']},{title:'EVOLUÇÃO',pages:['challenges','reports','profile']}],headings=[...nav.querySelectorAll(':scope>p')];groups.forEach((group,index)=>{let heading=headings[index-1];if(group.title&&heading){heading.textContent=group.title;nav.appendChild(heading)}group.pages.slice().sort((a,b)=>order.indexOf(a)-order.indexOf(b)).forEach(page=>{let button=nav.querySelector(`[data-page="${page}"]`);if(button)nav.appendChild(button)})})}
function moveNavigationItem(page,direction){let order=navigationOrder(),index=order.indexOf(page),next=index+direction;if(index<0||next<0||next>=order.length)return;[order[index],order[next]]=[order[next],order[index]];state.profile.navigationOrder=order;writeLocalState();scheduleCloudSave();ensureCategoryControls(true);applyNavigationOrder()}
