function setCategoryVisibility(page,visible){if(!NAV_CATEGORY_OPTIONS.some(([id])=>id===page))return;state.profile.categoryVisibility={...(state.profile.categoryVisibility||{}),[page]:!!visible};writeLocalState();scheduleCloudSave();syncCategoryVisibility();toast(visible?'Categoria ativada':'Categoria ocultada',`${NAV_CATEGORY_OPTIONS.find(([id])=>id===page)?.[1]||page} ${visible?'voltou ao menu.':'não aparecerá no menu.'}`)}
