function ensureCategoryControls(rebuild=false){let settingsGrid=document.getElementById('settingsNavigationGrid');if(!settingsGrid)return;let previous=settingsGrid.querySelector('.category-visibility-card');if(rebuild)previous?.remove();if(!settingsGrid.querySelector('.category-visibility-card')){let order=navigationOrder(),lookup=Object.fromEntries(NAV_CATEGORY_OPTIONS.map(item=>[item[0],item]));settingsGrid.insertAdjacentHTML('afterbegin',`<article class="card settings-card category-visibility-card"><span>MENU PRINCIPAL</span><h3>Categorias visíveis e ordem</h3><p>Ative somente o que usa e arraste os itens para reorganizar. Meu dia e Humor começam desativados.</p><div class="category-visibility-list">${order.map(page=>{let[,label,copy]=lookup[page];return`<div class="category-setting-row" draggable="true" data-navigation-item="${page}"><b class="drag-handle" aria-hidden="true">⠿</b><label><input type="checkbox" data-category-visibility="${page}"><i></i><b>${label}<small>${copy}</small></b></label><span><button type="button" data-nav-move="-1" aria-label="Mover ${label} para cima">↑</button><button type="button" data-nav-move="1" aria-label="Mover ${label} para baixo">↓</button></span></div>`}).join('')}</div><button class="secondary restore-navigation" id="restoreNavigationOrder" type="button">Restaurar organização padrão</button></article>`)}document.querySelectorAll('[data-category-visibility]').forEach(input=>input.onchange=()=>setCategoryVisibility(input.dataset.categoryVisibility,input.checked));document.querySelectorAll('[data-nav-move]').forEach(button=>button.onclick=()=>moveNavigationItem(button.closest('[data-navigation-item]').dataset.navigationItem,+button.dataset.navMove));let dragged='';document.querySelectorAll('[data-navigation-item]').forEach(row=>{row.ondragstart=()=>{dragged=row.dataset.navigationItem;row.classList.add('dragging')};row.ondragend=()=>{row.classList.remove('dragging');dragged=''};row.ondragover=event=>event.preventDefault();row.ondrop=event=>{event.preventDefault();let target=row.dataset.navigationItem,order=navigationOrder(),from=order.indexOf(dragged),to=order.indexOf(target);if(from<0||to<0||from===to)return;order.splice(to,0,order.splice(from,1)[0]);state.profile.navigationOrder=order;writeLocalState();scheduleCloudSave();ensureCategoryControls(true);applyNavigationOrder()}});let restore=document.getElementById('restoreNavigationOrder');if(restore)restore.onclick=()=>{state.profile.navigationOrder=NAV_CATEGORY_OPTIONS.map(([page])=>page);writeLocalState();scheduleCloudSave();ensureCategoryControls(true);applyNavigationOrder();toast('Organização restaurada','O menu voltou à ordem padrão.')};let moodButton=document.getElementById('profileMoodToggle');if(moodButton)moodButton.onclick=()=>setCategoryVisibility('mood',!categoryVisible('mood'));syncCategoryVisibility()}
