function localStateKey(){return currentUser?.id?`luar-state:${currentUser.id}`:'luar-state'}
const BROWSER_STATE_DB='luar-browser-state',BROWSER_STATE_STORE='accounts';
function openBrowserStateDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(new Error('IndexedDB indisponível'));let request=indexedDB.open(BROWSER_STATE_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(BROWSER_STATE_STORE))request.result.createObjectStore(BROWSER_STATE_STORE,{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Falha ao abrir IndexedDB'))})}
async function readBrowserState(userId){if(!userId)return null;try{let db=await openBrowserStateDB(),stored=await new Promise((resolve,reject)=>{let request=db.transaction(BROWSER_STATE_STORE,'readonly').objectStore(BROWSER_STATE_STORE).get(userId);request.onsuccess=()=>resolve(request.result?.state||null);request.onerror=()=>reject(request.error)});db.close();return stored}catch(error){console.warn('LUAR IndexedDB read:',error.message);return null}}
