function localStorageSnapshot(data=state){let snapshot=structuredClone(data),profile=snapshot.profile||{};if(/^data:image\//i.test(String(profile.avatar||'')))delete profile.avatar;if(/^data:image\//i.test(String(profile.customBanner||'')))delete profile.customBanner;snapshot.profile=profile;return snapshot}
function storeLocalState(key,data=state){try{localStorage.setItem(key,JSON.stringify(data));return true}catch(error){console.warn('LUAR localStorage:',error.message);try{localStorage.setItem(key,JSON.stringify(localStorageSnapshot(data)));return true}catch(fallbackError){console.warn('LUAR localStorage fallback:',fallbackError.message);return false}}}
function permanentProfileKey(){return currentUser?.id?`luar-permanent:${currentUser.id}`:'luar-permanent'}
function mergePermanentProfile(profile={}){let stored={};try{stored=JSON.parse(localStorage.getItem(permanentProfileKey())||'{}')}catch{}let achievements={...(stored.achievements||{}),...(profile.achievements||{})},achievementXP=Object.values(achievements).reduce((sum,item)=>sum+Math.max(0,+item?.xp||0),0),firstDates=[stored.firstSeenAt,profile.firstSeenAt,currentUser?.created_at].filter(Boolean).sort(),lastDates=[stored.lastAccessAt,profile.lastAccessAt].filter(Boolean).sort();return{...profile,achievements,xp:Math.max(0,+profile.xp||0,achievementXP),firstSeenAt:firstDates[0]||new Date().toISOString(),lastAccessAt:lastDates.at(-1)||new Date().toISOString(),accessCount:Math.max(+stored.accessCount||0,+profile.accessCount||0),record:Math.max(+stored.record||0,+profile.record||0)}}
