function writeLocalState(){state.profile=state.profile||{};state.profile.localUpdatedAt=new Date().toISOString();persistPermanentProfile();let stored=storeLocalState(localStateKey(),state);persistBrowserState(state);return stored}
function save(){recordPortfolioSnapshot();writeLocalState();scheduleCloudSave();render();if(!localStorage.getItem('luar-first-feature-tracked')&&stateHasContent(state)){localStorage.setItem('luar-first-feature-tracked','1');trackEvent('first_feature_use')}}
function recordPortfolioSnapshot(){state.portfolioHistory=Array.isArray(state.portfolioHistory)?state.portfolioHistory:[];let t=totals(),value=t.wealth,invested=t.goalSaved,date=today(),found=state.portfolioHistory.find(x=>x.date===date);if(found){found.value=value;found.invested=invested}else state.portfolioHistory.push({date,value,invested});state.portfolioHistory=state.portfolioHistory.slice(-730)}
function goalsSavedAt(key=today()){return state.goals.reduce((total,goal)=>{let deposits=goal.deposits||[],depositedTotal=deposits.reduce((sum,item)=>sum+(+item.amount||0),0),base=Math.max(0,(+goal.current||0)-depositedTotal),created=localDateKey(goal.createdAt||goal.date||today()),value=created<=key?base:0;value+=deposits.filter(item=>localDateKey(item.date||item.createdAt)<=key).reduce((sum,item)=>sum+(+item.amount||0),0);return total+value},0)}
function goalDepositsForMonth(key=monthKey()){return state.goals.reduce((total,goal)=>total+(goal.deposits||[]).filter(item=>localDateKey(item.date||item.createdAt).slice(0,7)===key).reduce((sum,item)=>sum+(+item.amount||0),0),0)}
function goalDepositsAt(key=today()){return state.goals.reduce((total,goal)=>total+(goal.deposits||[]).filter(item=>localDateKey(item.date||item.createdAt)<=key).reduce((sum,item)=>sum+(+item.amount||0),0),0)}
function summarizeTransactions(items=[]){let income=items.filter(x=>x.type==='income').reduce((sum,x)=>sum+(+x.amount||0),0),spending=items.filter(x=>x.type==='expense').reduce((sum,x)=>sum+(+x.amount||0),0),purchases=items.filter(x=>x.type==='purchase').reduce((sum,x)=>sum+(+x.amount||0),0),expense=spending+purchases;return{income,spending,purchases,expense,balance:income-expense}}
