function monthTotals(key=monthKey()){let summary=summarizeTransactions(transactionsForMonth(key)),goalDeposited=goalDepositsForMonth(key),goalSaved=goalsSavedAt();return{...summary,goalSaved,goalDeposited,balance:summary.balance}}
function totals(){let summary=summarizeTransactions(state.transactions),goalSaved=goalsSavedAt(),goalTransfers=goalDepositsAt(),balance=summary.balance;return{...summary,balance,invested:goalSaved,current:goalSaved,goalSaved,goalTransfers,wealth:balance+goalSaved}}

