function bindSettingsHub(){let hub=document.getElementById('settingsHub');if(!hub)return;hub.querySelectorAll('[data-settings-category]').forEach(button=>button.onclick=()=>selectSettingsCategory(button.dataset.settingsCategory));document.getElementById('settingsMobileBack').onclick=()=>hub.classList.remove('settings-detail-open');let search=document.getElementById('settingsSearch');search.oninput=()=>{let query=search.value.trim().toLocaleLowerCase('pt-BR'),first=null;hub.querySelectorAll('[data-settings-category]').forEach(button=>{let panel=hub.querySelector(`[data-settings-panel="${button.dataset.settingsCategory}"]`),match=!query||`${button.textContent} ${panel?.dataset.settingsSearch||''} ${panel?.textContent||''}`.toLocaleLowerCase('pt-BR').includes(query);button.hidden=!match;if(match&&!first)first=button});if(query&&first)selectSettingsCategory(first.dataset.settingsCategory,false)};document.querySelectorAll('[data-settings-theme]').forEach(button=>button.onclick=()=>setSettingsTheme(button.dataset.settingsTheme));let profileButton=document.getElementById('openProfileAppearance');if(profileButton)profileButton.onclick=()=>showPage('profile');let animation=document.getElementById('settingsAnimationToggle');if(animation)animation.onclick=()=>{if(!lifetimeActive)return showPremiumGate('Controle de animações','Pause todas as animações e transições com o LUAR Vitalício.');state.profile.animationsEnabled=state.profile.animationsEnabled===false;writeLocalState();scheduleCloudSave();applyMotionPreference();syncSettingsHubControls()};let summary=document.getElementById('settingsAccountSummary'),security=document.getElementById('settingsSecurityOptions'),name=state.profile.name||currentUser?.user_metadata?.name||currentUser?.email?.split('@')[0]||'Conta LUAR',email=currentUser?.email||'E-mail indisponível',avatar=profileAvatarUrl(),initials=name.split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase(),providers=[...new Set((currentUser?.identities||[]).map(identity=>String(identity.provider||'').toLowerCase()))],providerLabels={google:'Google',discord:'Discord',email:'E-mail e senha'};if(summary)summary.innerHTML=`<span>PERFIL</span><div class="settings-account-identity"><i class="${avatar?'has-avatar':''}" ${avatar?`style="background-image:url('${safe(avatar)}')"`:''}>${avatar?'':safe(initials)}</i><div><h3>${safe(name)}</h3><p>${safe(email)}</p><small>${lifetimeActive?'✦ Plano Vitalício ativo':'Plano gratuito'}</small></div><button type="button" class="secondary" data-page="profile">Editar perfil</button></div>`;if(security)security.innerHTML=`<span>ACESSO</span><h3>Conta e segurança</h3><div class="security-setting-list"><div><i>@</i><span><b>E-mail</b><small>${safe(email)}</small></span><em>Confirmado</em></div><div><i>⌁</i><span><b>Contas conectadas</b><small>${providers.length?providers.map(provider=>providerLabels[provider]||provider).join(' · '):providerLabels[currentUser?.app_metadata?.provider]||'E-mail e senha'}</small></span><em>Ativas</em></div><button type="button" id="settingsChangePassword"><i>••</i><span><b>Alterar senha</b><small>Receba um link seguro por e-mail</small></span><em>›</em></button><div><i>▣</i><span><b>Sessões e dispositivos</b><small>Gerenciamento detalhado de acessos</small></span><em class="soon">Em breve</em></div><div><i>◎</i><span><b>Autenticação em duas etapas</b><small>Uma camada adicional de proteção</small></span><em class="soon">Em breve</em></div></div><button type="button" class="secondary settings-signout" id="settingsSignOut">Sair da conta</button>`;document.getElementById('settingsChangePassword')?.addEventListener('click',()=>{openAuth('recovery');document.querySelector('#authForm [name="email"]')?.setAttribute('value',email)});document.getElementById('settingsSignOut')?.addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await supabaseClient?.auth.signOut()}catch(error){event.currentTarget.disabled=false;toast('Não foi possível sair',error.message)}});syncSettingsHubControls();selectSettingsCategory(activeSettingsCategory,false)}
let budgetSliceSelection='income';
function selectBudgetSlice(key,chart=document.getElementById('budgetPercentChart')){let slice=chart?._budgetSlices?.find(item=>item.key===key)||chart?._budgetSlices?.[0],visual=chart?.querySelector('.budget-orbit-visual');if(!slice||!visual)return;budgetSliceSelection=slice.key;chart.querySelectorAll('[data-budget-slice]').forEach(button=>button.classList.toggle('active',button.dataset.budgetSlice===slice.key));visual.setAttribute('aria-label',`${slice.label}: ${money(slice.value)} — ${slice.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}% do movimento mensal`)}
function setBudgetOrbitTooltip(chart,slice,event){let visual=chart?.querySelector('.budget-orbit-visual'),tooltip=visual?.querySelector('.budget-orbit-tooltip');if(!tooltip)return;if(!slice){tooltip.hidden=true;visual.classList.remove('inspecting');return}let rect=visual.getBoundingClientRect(),rawX=event?.clientX-rect.left||rect.width/2,rawY=event?.clientY-rect.top||rect.height/2,x=Math.max(78,Math.min(rect.width-78,rawX)),y=Math.max(18,Math.min(rect.height-18,rawY)),percent=slice.percent.toLocaleString('pt-BR',{maximumFractionDigits:1});tooltip.innerHTML=`<span><i style="background:${slice.color}"></i>${slice.label}</span><b>${money(slice.value)}</b><small>${percent}% do movimento mensal</small>`;tooltip.style.left=`${x}px`;tooltip.style.top=`${y}px`;tooltip.dataset.placement=rawY<92?'below':'above';tooltip.hidden=false;visual.classList.add('inspecting')}
function renderBudgetOrbit(){let chart=document.getElementById('budgetPercentChart');if(!chart)return;let t=monthTotals(),slices=[{key:'income',label:'Recebimentos',value:Math.max(0,t.income),color:'#32ff7e'},{key:'spending',label:'Gastos',value:Math.max(0,t.spending),color:'#ff6577'},{key:'purchases',label:'Compras',value:Math.max(0,t.purchases),color:'#ffb960'},{key:'goals',label:'Metas',value:Math.max(0,t.goalSaved),color:'#a983ff'}],total=slices.reduce((sum,item)=>sum+item.value,0),cursor=0;chart._budgetSlices=slices.map(item=>{let percent=total?item.value/total*100:0,start=cursor,end=cursor+percent*3.6;cursor=end;return{...item,percent,start,end}});let gradient=total?`conic-gradient(${chart._budgetSlices.map(item=>`${item.color} ${item.start}deg ${item.end}deg`).join(',')})`:'conic-gradient(rgba(255,255,255,.07) 0 360deg)';chart.classList.add('budget-orbit-chart');chart.innerHTML=`<div class="budget-orbit-visual" style="background:${gradient}" role="img" tabindex="0" aria-label="Distribuição interativa do orçamento mensal. Use as setas para explorar."><span class="budget-orbit-hole" aria-hidden="true"></span><aside class="budget-orbit-tooltip" role="status" aria-live="polite" hidden></aside></div><div class="budget-orbit-legend">${chart._budgetSlices.map(item=>`<button type="button" data-budget-slice="${item.key}"><i style="background:${item.color}"></i><span>${item.label}<small>${money(item.value)}</small></span><b>${item.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</b><u><em style="width:${item.percent}%;background:${item.color}"></em></u></button>`).join('')}</div>`;let visual=chart.querySelector('.budget-orbit-visual'),sliceAt=event=>{if(!total)return null;let rect=visual.getBoundingClientRect(),dx=event.clientX-(rect.left+rect.width/2),dy=event.clientY-(rect.top+rect.height/2),distance=Math.hypot(dx,dy);if(distance<rect.width*.23||distance>rect.width*.5)return null;let angle=(Math.atan2(dx,-dy)*180/Math.PI+360)%360;return chart._budgetSlices.find(item=>angle>=item.start&&angle<item.end)};visual.onpointermove=event=>{let slice=sliceAt(event);if(!slice)return setBudgetOrbitTooltip(chart,null);selectBudgetSlice(slice.key,chart);setBudgetOrbitTooltip(chart,slice,event)};visual.onpointerleave=()=>setBudgetOrbitTooltip(chart,null);visual.onblur=()=>setBudgetOrbitTooltip(chart,null);visual.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();let direction=['ArrowRight','ArrowDown'].includes(event.key)?1:-1,index=chart._budgetSlices.findIndex(item=>item.key===budgetSliceSelection),slice=chart._budgetSlices[(index+direction+chart._budgetSlices.length)%chart._budgetSlices.length];selectBudgetSlice(slice.key,chart);setBudgetOrbitTooltip(chart,slice)};chart.querySelectorAll('[data-budget-slice]').forEach(button=>{button.onpointerenter=button.onclick=()=>selectBudgetSlice(button.dataset.budgetSlice,chart)});selectBudgetSlice(chart._budgetSlices.some(item=>item.key===budgetSliceSelection&&item.value>0)?budgetSliceSelection:(chart._budgetSlices.find(item=>item.value>0)?.key||'income'),chart)}
function renderSafeBudget(){let t=monthTotals(),available=Math.max(0,t.balance),availableEl=document.getElementById('budgetAvailable'),status=document.getElementById('budgetStatus');if(availableEl)availableEl.textContent=money(available);if(status){status.textContent=t.balance>0?'Orçamento positivo':t.balance<0?'Sem saldo livre neste mês':'Orçamento equilibrado';status.className=t.balance>=0?'up':'down'}renderBudgetOrbit()}

