let productTourIndex=0;
function startProductTour(force=false){if(!currentUser||(!force&&state.profile.siteTourCompleted))return;let layer=document.getElementById('productTour');if(!layer){document.body.insertAdjacentHTML('beforeend','<div class="product-tour" id="productTour" aria-live="polite"><section><span id="tourProgress"></span><h2 id="tourTitle"></h2><p id="tourCopy"></p><small id="tourPlan"></small><footer><button class="secondary" id="tourSkip">Pular apresentação</button><button class="primary" id="tourNext">Próximo →</button></footer></section></div>');layer=document.getElementById('productTour');document.getElementById('tourSkip').onclick=finishProductTour;document.getElementById('tourNext').onclick=()=>{productTourIndex++;productTourIndex>=PRODUCT_TOUR.length?finishProductTour():showProductTourStep()}}productTourIndex=0;document.body.classList.add('product-tour-active');layer.classList.add('open');showProductTourStep()}
function showProductTourStep(){let step=PRODUCT_TOUR[productTourIndex],layer=document.getElementById('productTour');document.querySelectorAll('.tour-highlight').forEach(x=>x.classList.remove('tour-highlight'));showPage(step.page);setTimeout(()=>{let target=document.querySelector(step.selector);target?.classList.add('tour-highlight');target?.scrollIntoView({behavior:'smooth',block:'center'})},80);document.getElementById('tourProgress').textContent=`GUIA DO PRIMEIRO ACESSO • ${productTourIndex+1} DE ${PRODUCT_TOUR.length}`;document.getElementById('tourTitle').textContent=step.title;document.getElementById('tourCopy').textContent=step.copy;document.getElementById('tourPlan').textContent=lifetimeActive?'✦ Sua conta LUAR Vitalício está ativa: todos os recursos desta apresentação estão liberados.':'Plano gratuito ativo: quando um recurso for Vitalício, o LUAR avisará sem bloquear o restante da plataforma.';document.getElementById('tourNext').textContent=productTourIndex===PRODUCT_TOUR.length-1?'Começar a usar ✓':'Próximo →';layer.classList.add('open')}
function finishProductTour(){document.getElementById('productTour')?.classList.remove('open');document.body.classList.remove('product-tour-active');document.querySelectorAll('.tour-highlight').forEach(x=>x.classList.remove('tour-highlight'));state.profile.siteTourCompleted=true;writeLocalState();scheduleCloudSave();showPage('dashboard');toast('Apresentação concluída','Agora sua órbita está pronta para começar.');setTimeout(()=>window.LuarDailyQuote?.start(currentUser),450)}

