function buildProfileAvatarControl(){let grid=document.getElementById('settingsAccountGrid'),card=grid?.querySelector('.account-card');if(!card||card.querySelector('.avatar-upload'))return;let currentUrl=allowedAvatarUrl(state.profile.avatar),uploaded=currentUrl.startsWith('data:');card.querySelector('.account-user')?.insertAdjacentHTML('afterend',`<div class="avatar-upload avatar-link-only"><div id="avatarPreview">${currentUrl?`<img src="${safe(currentUrl)}" alt="Seu ícone">`:'✦'}</div><span><b>Seu ícone</b><small>${uploaded?'Foto enviada pelo Perfil Cósmico e salva na conta.':'Use um link público HTTPS de uma imagem JPG, PNG ou WebP.'}</small></span>${currentUrl?'<button type="button" id="removeAvatar">Remover</button>':''}<div class="avatar-link-row"><label for="avatarUrl">Link da imagem<input id="avatarUrl" type="url" inputmode="url" autocomplete="url" placeholder="https://exemplo.com/minha-imagem.png" value="${safe(uploaded?'':currentUrl)}"></label><button type="button" id="applyAvatarUrl">Usar link</button></div></div>`);let applyAvatar=avatar=>{state.profile.avatar=avatar;save();buildPages();render();showPage('settings');toast('Ícone atualizado','Sua imagem agora aparece no perfil.')};document.getElementById('applyAvatarUrl').onclick=()=>{let value=document.getElementById('avatarUrl').value.trim(),url=allowedAvatarUrl(value);if(!url)return toast('Link inválido','Use um endereço público que comece com https://.');let image=new Image();image.referrerPolicy='no-referrer';image.onload=()=>applyAvatar(url);image.onerror=()=>toast('Imagem não encontrada','Verifique se o link abre uma imagem pública.');image.src=url};let remove=document.getElementById('removeAvatar');if(remove)remove.onclick=()=>{delete state.profile.avatar;save();buildPages();render();showPage('settings')}}
function monthKey(){return today().slice(0,7)}
function subscriptionPaid(subscription){return Array.isArray(subscription.paidMonths)&&subscription.paidMonths.includes(monthKey())}
function markSubscriptionPaid(subscriptionId){let sub=state.subscriptions.find(x=>x.id===subscriptionId);if(!sub)return;sub.paidMonths=Array.isArray(sub.paidMonths)?sub.paidMonths:[];let key=monthKey(),transaction=state.transactions.find(x=>x.subscriptionId===sub.id&&x.monthKey===key);if(sub.paidMonths.includes(key)){sub.paidMonths=sub.paidMonths.filter(x=>x!==key);if(transaction)state.transactions=state.transactions.filter(x=>x.id!==transaction.id);save();toast('Pagamento desmarcado','O gasto automático deste mês foi removido.');return}sub.paidMonths.push(key);if(!transaction)state.transactions.push({id:id(),subscriptionId:sub.id,monthKey:key,type:'expense',name:sub.name,amount:+sub.amount||0,category:'Assinaturas',date:today(),createdAt:new Date().toISOString()});let earned=awardXP(`subscription-paid:${sub.id}:${key}`,3);save();toast(earned?'+3 XP • Assinatura paga':'Assinatura paga',`${money(sub.amount)} foi adicionado aos gastos deste mês.`)}
function reportDays(){let now=new Date(),start,end;if(reportPeriod==='Semana anterior'){end=new Date(now);end.setDate(end.getDate()-7);start=new Date(end);start.setDate(start.getDate()-6)}else if(reportPeriod==='Últimos 30 dias'){end=now;start=new Date(now);start.setDate(start.getDate()-29)}else if(reportPeriod==='Este mês'){end=now;start=new Date(now.getFullYear(),now.getMonth(),1)}else if(reportPeriod==='Período personalizado'&&reportCustomStart&&reportCustomEnd){start=new Date(reportCustomStart+'T12:00:00');end=new Date(reportCustomEnd+'T12:00:00');if(start>end)[start,end]=[end,start]}else{end=now;start=new Date(now);start.setDate(start.getDate()-6)}let days=[];for(let cursor=new Date(start);cursor<=end;cursor.setDate(cursor.getDate()+1))days.push(dateKey(cursor));return days.slice(-366)}
