function renderChallengeCards(filter='Todos'){state.profile.challenges=state.profile.challenges||{};let root=document.getElementById('challengeGrid');if(!root)return;let items=ADVANCED_CHALLENGES.filter(x=>filter==='Todos'||x[0]===filter),groups=[...new Set(items.map(x=>x[0]))];root.innerHTML=groups.map(group=>`<section><h2>${group}</h2><div>${items.filter(x=>x[0]===group).map(([category,key,name,description,target,xp,difficulty])=>{let progress=Math.min(target,+state.profile.challenges[key]||0),pct=Math.round(progress/target*100),streak=Math.min(progress,7),registered=challengeRegisteredToday(key);return `<article class="card challenge-model"><header><span>${category} · ${difficulty}</span><b>+${xp} XP</b></header><h3>${name}</h3><p>${description}</p><div class="challenge-blocks">${Array.from({length:Math.min(target,7)},(_,i)=>`<i class="${i<progress?'done':''}"></i>`).join('')}<small>${progress} de ${target}${target===100?' reais':' dias'}</small></div><footer><span>🔥 ${streak} dias registrados</span><span>⏳ Faltam ${Math.max(0,target-progress)}</span></footer><button class="primary full" data-challenge-progress="${key}" ${registered||progress>=target?'disabled':''}>${progress>=target?'✓ Desafio concluído':registered?'✓ Registrado hoje':'Registrar dia'}</button></article>`}).join('')}</div></section>`).join('')}
function metricsForDays(days){let set=new Set(days),taskCounts=days.map(d=>state.tasks.filter(x=>x.completed&&localDateKey(x.completedAt||x.createdAt||x.date)===d).length),habitCounts=days.map(d=>state.habits.reduce((sum,x)=>sum+Number((x.history||[]).includes(d)),0)),focusCounts=days.map(d=>state.focusSessions.filter(x=>localDateKey(x.date||x.createdAt)===d).reduce((sum,x)=>sum+(+x.minutes||0),0)),periodTransactions=state.transactions.filter(x=>set.has(localDateKey(x.date||x.createdAt))),finance=summarizeTransactions(periodTransactions),moods=state.moods.filter(x=>set.has(localDateKey(x.date||x.createdAt))),activeDays=days.filter((d,i)=>taskCounts[i]+habitCounts[i]+focusCounts[i]+moods.filter(x=>localDateKey(x.date||x.createdAt)===d).length+periodTransactions.filter(x=>localDateKey(x.date||x.createdAt)===d).length>0).length;return{days,set,taskCounts,habitCounts,focusCounts,periodTransactions,finance,moods,activeDays,completed:taskCounts.reduce((a,b)=>a+b,0),habitTotal:habitCounts.reduce((a,b)=>a+b,0),focusTotal:focusCounts.reduce((a,b)=>a+b,0),saved:Math.max(0,finance.balance)}}
function reportComparison(value,previous,kind='number'){let delta=value-previous,sign=delta>0?'+':delta<0?'−':'',absolute=Math.abs(delta);if(kind==='money')return `${sign}${money(absolute)}`;if(kind==='focus')return `${sign}${formatFocus(absolute)}`;return `${sign}${Math.round(absolute)}`}
