function shiftDateKey(key,days){let[year,month,day]=String(key).split('-').map(Number),date=new Date(Date.UTC(year,month-1,day+days));return`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
