async function restoreCloudVersion(version){if(!confirm(`Restaurar o arquivo salvo em ${new Date(version.savedAt).toLocaleString('pt-BR')}? Os dados atuais serão substituídos.`))return;try{clearTimeout(cloudSaveTimer);cloudSaveTimer=null;cloudSaveQueued=false;if(cloudSaveInFlight)await cloudSaveInFlight;clearTimeout(cloudSaveTimer);cloudSaveTimer=null;cloudSaveQueued=false;let response=await accountApiFetch('/api/account-state',{method:'POST',body:JSON.stringify({action:'restoreBackup',savedAt:version.savedAt})}),result=await readApiJson(response);if(!response.ok||!result.state)throw new Error(result.error||'Não foi possível abrir esta versão.');let retainedMedia={avatar:state.profile?.avatar,customBanner:state.profile?.customBanner};applyAccountState(result.state);state.profile=state.profile||{};if(!state.profile.avatar&&/^data:image\/(?:png|jpe?g|webp);base64,/i.test(String(retainedMedia.avatar||'')))state.profile.avatar=retainedMedia.avatar;if(!state.profile.customBanner&&/^data:image\/(?:png|jpe?g|webp);base64,/i.test(String(retainedMedia.customBanner||'')))state.profile.customBanner=retainedMedia.customBanner;state.profile.localUpdatedAt=result.updatedAt||new Date().toISOString();persistPermanentProfile();storeLocalState(localStateKey(),state);persistBrowserState(state);cloudAccount={...(cloudAccount||{}),state:structuredClone(result.state),updatedAt:result.updatedAt,backups:Array.isArray(result.backups)?result.backups:cloudAccount?.backups||[]};buildPages();render();showPage('dashboard');toast('Versão restaurada','A cópia escolhida voltou e o estado anterior ficou guardado no histórico.')}catch(error){toast('Não foi possível restaurar',error.message)}}
function restoreCloudState(){if(!lifetimeActive)return showPremiumGate('Restaurar backup da nuvem','Recupere backups manuais salvos no Supabase com o LUAR Vitalício.');let history=Array.isArray(cloudAccount?.backups)?cloudAccount.backups.slice(0,10):[];if(!history.length)return toast('Nenhuma versão salva','Clique em “Criar nova versão” antes de restaurar.');document.getElementById('modalKicker').textContent='HISTÓRICO NA NUVEM';document.getElementById('modalTitle').textContent=`Restaurar uma das ${history.length} versões`;document.getElementById('entityForm').innerHTML=`<div class="cloud-restore-list"><p>Escolha a versão que será devolvida à sua conta. Seus dados atuais só mudam depois da confirmação.</p>${history.map((version,index)=>`<button type="button" data-cloud-version="${index}"><i>↶</i><span><b>${index===0?'Versão mais recente':`Versão ${index+1} de ${history.length}`}</b><small>${new Date(version.savedAt).toLocaleString('pt-BR')} · ${formatBackupSize(version.size)}</small></span><em>Restaurar ↗</em></button>`).join('')}</div>`;document.getElementById('backdrop').classList.add('open');document.querySelectorAll('[data-cloud-version]').forEach(button=>button.onclick=async()=>{document.getElementById('backdrop').classList.remove('open');await restoreCloudVersion(history[+button.dataset.cloudVersion])})}
