async function previousMarketClose(x){if(x.provider==='fixed')return +x.price||0;let token=CFG.market?.brapiToken||'',key=CFG.market?.twelveDataKey||'demo';try{if(x.provider==='brapi'){let r=await fetch(`https://brapi.dev/api/v2/stocks/historical?symbols=${encodeURIComponent(x.ticker)}&range=5d&interval=1d&sortOrder=asc`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json(),data=j.results?.[0]?.data||j.results?.[0]?.historicalDataPrice||[],closes=data.map(v=>({date:String(v.date||v.datetime||''),close:+(v.close||v.adjustedClose)})).filter(v=>Number.isFinite(v.close));return closes.filter(v=>!v.date||v.date.slice(0,10)<today()).at(-1)?.close||closes.at(-2)?.close||closes.at(-1)?.close||+x.price||0}let r=await fetch(`https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(x.ticker)}&interval=1day&outputsize=7&apikey=${encodeURIComponent(key)}`),j=await r.json(),values=(j.values||[]).map(v=>({date:String(v.datetime||''),close:+v.close})).filter(v=>Number.isFinite(v.close));return values.find(v=>v.date.slice(0,10)<today())?.close||values[1]?.close||values[0]?.close||+x.price||0}catch{return +x.price||0}}
