function startStopwatchSession(){if(!lifetimeActive)return showPremiumGate('Cronômetro de foco','Use o cronômetro livre, acompanhe a orbe no cabeçalho e some o tempo real ao seu histórico com o LUAR Vitalício.');if(countdownActive||ticker)resetCountdown(true);if(!stopwatchEnabled){stopwatchEnabled=true;stopwatchBaseSeconds=0;stopwatchSessionId=id();stopwatchCreatedAt=new Date().toISOString();focusOwnerKey=localStateKey();lastStopwatchPersistAt=Date.now()}if(!stopwatchRunning){stopwatchStartedAt=Date.now();stopwatchRunning=true;runStopwatchTicker()}renderFocusHeader();toast('Cronômetro em órbita','A orbe no cabeçalho acompanha cada segundo focado.')}
