function stopAmbient(update=true){ambient.timers.forEach(clearInterval);ambient.timers=[];ambient.nodes.forEach(n=>{try{n.stop?.()}catch{}try{n.disconnect?.()}catch{}});ambient.nodes=[];if(ambient.ctx){ambient.ctx.close().catch(()=>{});ambient.ctx=null}ambient.master=null;ambient.mode=null;document.querySelectorAll('[data-sound]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});if(update)document.getElementById('soundStatus').textContent='Som pausado. Escolha um ambiente para continuar.'}
function makeNoise(ctx,seconds=3){let buffer=ctx.createBuffer(2,ctx.sampleRate*seconds,ctx.sampleRate);for(let c=0;c<2;c++){let data=buffer.getChannelData(c),last=0;for(let i=0;i<data.length;i++){let white=Math.random()*2-1;last=(last+.025*white)/1.025;data[i]=white*.55+last*1.7}}return buffer}
