function playAmbient(mode,button){if(ambient.mode===mode){stopAmbient();return}stopAmbient(false);let AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext){document.getElementById('soundStatus').textContent='Seu navegador não oferece suporte a áudio ambiente.';return}let ctx=new AudioContext();ambient.ctx=ctx;ambient.master=ctx.createGain();ambient.master.gain.value=(+document.getElementById('ambientVolume').value||32)/100;ambient.master.connect(ctx.destination);ambient.nodes.push(ambient.master);ambient.mode=mode;if(mode==='lofi')startLofi(ctx);else{addNoise(ctx,mode);if(mode==='forest'){forestChirp(ctx);ambient.timers.push(setInterval(()=>forestChirp(ctx),1800+Math.random()*1800))}}button.classList.add('active');button.setAttribute('aria-pressed','true');document.getElementById('soundStatus').textContent=`Tocando: ${soundNames[mode]} • clique novamente para pausar.`;ctx.resume()}
