const ACCOUNT_COLLECTIONS=['transactions','tasks','habits','goals','subscriptions','wishlist','investments','events','moods','notes','focusSessions','portfolioHistory'];
function stateContentCount(value){return ACCOUNT_COLLECTIONS.reduce((total,key)=>total+(Array.isArray(value?.[key])?value[key].length:0),0)}
