function chooseSafestAccountState(candidates,remoteUpdatedAt,userId){let valid=candidates.filter(item=>item?.state&&typeof item.state==='object'),remote=valid.find(item=>item.source==='cloud'),remoteCount=stateContentCount(remote?.state),migrationKey=`luar-state-recovery-v3:${userId}`,migrationDone=localStorage.getItem(migrationKey)==='1';if(remoteCount){let newer=valid.filter(item=>item.source!=='cloud'&&stateTimestamp(item.state)>Date.parse(remoteUpdatedAt||'')&&stateContentCount(item.state)).sort((a,b)=>stateTimestamp(b.state)-stateTimestamp(a.state))[0];if(newer)return{...newer,upload:true};if(!migrationDone){let richer=valid.filter(item=>item.source!=='cloud'&&stateContentCount(item.state)>remoteCount).sort((a,b)=>stateContentCount(b.state)-stateContentCount(a.state))[0];localStorage.setItem(migrationKey,'1');if(richer)return{...richer,upload:true}}return remote}let richest=valid.filter(item=>stateContentCount(item.state)).sort((a,b)=>stateContentCount(b.state)-stateContentCount(a.state)||stateTimestamp(b.state)-stateTimestamp(a.state))[0];return richest?{...richest,upload:richest.source!=='cloud'}:(remote||valid[0]||{state:structuredClone(EMPTY),source:'empty'})}
async function pushCloudState({allowEmpty=false,createBackup=false,replaceOnConflict=false}={}){
 if(!currentUser||!supabaseClient)return false;
 if(allowEmpty)cloudSaveAllowEmpty=true;
 if((createBackup||replaceOnConflict)&&cloudSaveInFlight){await cloudSaveInFlight;return pushCloudState({allowEmpty,createBackup,replaceOnConflict})}
 if(cloudSaveInFlight){cloudSaveQueued=true;return cloudSaveInFlight}
 let snapshot=structuredClone(state),permitEmpty=cloudSaveAllowEmpty;cloudSaveAllowEmpty=false;
 cloudSaveInFlight=(async()=>{try{let saveOnce=async(payload,baseUpdatedAt)=>{let response=await accountApiFetch('/api/account-state',{method:'PUT',body:JSON.stringify({state:payload,allowEmpty:permitEmpty,createBackup,baseUpdatedAt})}),result=await readApiJson(response);return{response,result}};let{response,result}=await saveOnce(snapshot,cloudAccount?.updatedAt||null);if(response.status===409&&result.conflict&&result.state){if(!replaceOnConflict){snapshot=mergeAccountStates(result.state,snapshot);applyAccountState(snapshot);storeLocalState(localStateKey(),snapshot);persistBrowserState(snapshot);render()}({response,result}=await saveOnce(snapshot,result.updatedAt||null))}if(!response.ok){let error=new Error(result.error||'Falha ao salvar na nuvem.');error.status=response.status;throw error}cloudAccount=result;cloudRetryDelay=0;return true}catch(error){console.warn('LUAR cloud save:',error.message);if(![400,409,413].includes(error.status)){cloudRetryDelay=cloudRetryDelay?Math.min(cloudRetryDelay*2,30000):3000;scheduleCloudSave(cloudRetryDelay)}return false}})();
 let saved=await cloudSaveInFlight;cloudSaveInFlight=null;if(cloudSaveQueued){cloudSaveQueued=false;scheduleCloudSave(100)}return saved
}
