function ensureAdminLifetimeCard(){let grid=document.getElementById('settingsAboutGrid');if(!grid||!isLifetimeAdminSession()||grid.querySelector('.admin-lifetime-card'))return;grid.insertAdjacentHTML('beforeend',`<article class="card settings-card admin-lifetime-card"><span>ADMINISTRAÇÃO DO VITALÍCIO</span><h3>Gerenciar acesso por e-mail</h3><p>Conceda ou remova somente acessos administrativos. Compras e licenças permanentes continuam protegidas.</p><form id="adminLifetimeForm"><label>E-mail da conta<input type="email" name="email" autocomplete="off" required placeholder="pessoa@exemplo.com"></label><label>Plataforma<select name="provider"><option value="google">Google</option><option value="discord">Discord</option><option value="email">E-mail e senha</option></select></label><div><button class="primary" name="action" value="grant">Ativar Vitalício</button><button class="secondary danger-button" name="action" value="revoke">Remover concessão</button></div><small id="adminLifetimeStatus" role="status" aria-live="polite">A autorização será validada novamente no servidor.</small></form></article>`);let form=document.getElementById('adminLifetimeForm'),status=document.getElementById('adminLifetimeStatus');form.onsubmit=async event=>{event.preventDefault();let submitter=event.submitter,action=submitter?.value;if(!['grant','revoke'].includes(action))return;let data=new FormData(form),email=String(data.get('email')||'').trim().toLowerCase(),provider=String(data.get('provider')||'');form.querySelectorAll('button').forEach(button=>button.disabled=true);status.textContent=action==='grant'?'Ativando acesso…':'Verificando e removendo concessão…';status.className='pending';try{let response=await accountApiFetch('/api/admin-lifetime',{method:'POST',body:JSON.stringify({action,email,provider})}),result=await readApiJson(response);if(!response.ok)throw new Error(result.error||'Não foi possível alterar o plano.');status.className='success';status.textContent=result.lifetime?`Vitalício ativo para ${result.email} em todas as formas de login.`:`Concessão administrativa removida de ${result.email}.`;toast(result.lifetime?'Vitalício ativado':'Concessão removida',result.changed?'A alteração foi salva e auditada.':'A conta já estava com esse estado.');if(email===String(currentUser?.email||'').toLowerCase()){lifetimeActive=!!result.lifetime;buildPages();render();showPage('settings')}}catch(error){status.className='error';status.textContent=error.message}finally{form.querySelectorAll('button').forEach(button=>button.disabled=false)}}}
function captureGrowthSource(){let params=new URLSearchParams(location.search),ref=String(params.get('ref')||'').trim().toUpperCase();if(/^[A-Z0-9]{8,16}$/.test(ref))localStorage.setItem('luar-referral-code',ref);let attribution={};['utm_source','utm_medium','utm_campaign','utm_content','utm_term'].forEach(key=>{let value=String(params.get(key)||'').slice(0,120);if(value)attribution[key]=value});if(Object.keys(attribution).length){attribution.capturedAt=new Date().toISOString();localStorage.setItem('luar-attribution',JSON.stringify(attribution))}}
