async function copyReferralText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return true}}catch{}let input=document.createElement('textarea');input.value=text;input.readOnly=true;input.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(input);input.select();let copied=false;try{copied=document.execCommand('copy')}catch{}input.remove();return copied}
