document.getElementById('discordAuth').onclick=()=>signInWithSocial('discord');
document.getElementById('googleAuth').onclick=()=>signInWithSocial('google');
document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();if(!supabaseClient){authMessage('A conexão de conta ainda não está disponível.');return}let form=new FormData(e.target),email=String(form.get('email')||'').trim(),password=String(form.get('password')||''),name=String(form.get('name')||'').trim(),submit=e.target.querySelector('.auth-submit');submit.disabled=true;submit.textContent='Aguarde…';try{if(authMode==='login'){let{data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;trackEvent('login',{method:'email'});await handleSignedIn(data.user,data.session)}else if(authMode==='signup'){let response=await fetch('/api/create-account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,name})}),result=await readApiJson(response);if(!response.ok){let error=new Error(result.error||'Não foi possível criar a conta.');error.registered=response.status===409;throw error}if(result.requiresConfirmation){authMessage('Conta criada! Enviamos um link de verificação para seu e-mail. Confirme antes de entrar.',true);return}let{data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;trackEvent('sign_up',{method:'email'});authMessage('Conta criada! Entrando no LUAR…',true);await handleSignedIn(data.user,data.session)}else if(authMode==='recovery'){let{error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:new URL('#reset-password',AUTH_REDIRECT_URL).href});if(error)throw error;authMessage('Link de recuperação enviado. Confira seu e-mail.',true)}else if(authMode==='update'){let{error}=await supabaseClient.auth.updateUser({password});if(error)throw error;authMessage('Senha atualizada com sucesso.',true);setTimeout(()=>enterApp(),900)}}catch(error){let registered=error.registered||/already registered|already been registered|user already exists/i.test(error.message),message=/invalid login/i.test(error.message)?'E-mail ou senha incorretos.':registered?'Este e-mail já possui uma conta no LUAR.':error.message;authMessage(message,false,registered)}finally{submit.disabled=false;submit.textContent=authCopy(authMode)[3]}};
function resolveGuestSession(){currentSessionAuthentication=null;authResolutionFinished=true;clearTimeout(focusPeriodRefreshTimer);focusPeriodRefreshTimer=null;window.LuarDailyQuote?.stop();document.body.classList.remove('ads-auth-pending','lifetime-user');removeMonetagScripts();showLanding()}
if(supabaseClient){supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){currentUser=session?.user||null;currentSessionAuthentication=readSessionAuthentication(session,session?.user);authResolutionFinished=true;openAuth('update');return}if(event==='SIGNED_OUT'){stopAllFocusClocks(true);unloadCustomPlaylist();currentUser=null;currentSessionAuthentication=null;loadedUserId=null;cloudAccount=null;lifetimeActive=false;applyAccent();syncLandingAccount();resolveGuestSession();return}if(session?.user)setTimeout(()=>handleSignedIn(session.user,session),0);else if(event==='INITIAL_SESSION')showLanding()});supabaseClient.auth.getSession().then(({data})=>data.session?.user?handleSignedIn(data.session.user,data.session):resolveGuestSession()).catch(resolveGuestSession)}else resolveGuestSession();

function scheduleAdBlockCheck(){}
function bindLandingOrbitInteraction(){let hero=document.querySelector('.landing-hero'),orbit=hero?.querySelector('.landing-orbit');if(!hero||!orbit||hero.dataset.orbitBound)return;hero.dataset.orbitBound='true';hero.addEventListener('pointermove',event=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let bounds=hero.getBoundingClientRect(),x=(event.clientX-bounds.left)/bounds.width-.5,y=(event.clientY-bounds.top)/bounds.height-.5;orbit.style.setProperty('--orbit-x',`${Math.round(x*28)}px`);orbit.style.setProperty('--orbit-y',`${Math.round(y*14)}px`)});hero.addEventListener('pointerleave',()=>{orbit.style.setProperty('--orbit-x','0px');orbit.style.setProperty('--orbit-y','0px')})}

buildPages();render();chartHover();rt();bindLandingOrbitInteraction();if(location.hash&&document.getElementById(location.hash.slice(1))){showPage(location.hash.slice(1));requestAnimationFrame(()=>scrollTo(0,0));setTimeout(()=>scrollTo(0,0),80)}
function normalizeAppHeadingHierarchy(){document.querySelectorAll('body>main h1').forEach(heading=>{let replacement=document.createElement('h2');for(let attribute of heading.attributes)replacement.setAttribute(attribute.name,attribute.value);replacement.innerHTML=heading.innerHTML;heading.replaceWith(replacement)})}
let appHeadingRoot=document.querySelector('body>main');if(appHeadingRoot){new MutationObserver(normalizeAppHeadingHierarchy).observe(appHeadingRoot,{childList:true,subtree:true});normalizeAppHeadingHierarchy()}
document.getElementById('authForm')?.addEventListener('submit',()=>{if(authMode==='signup')trackEvent('sign_up_begin',{method:'email'})},{capture:true});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',async()=>{try{let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing||sessionStorage.getItem('luar-sw-refreshed')==='1')return;refreshing=true;sessionStorage.setItem('luar-sw-refreshed','1');location.reload()});let registration=await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});await registration.update()}catch(error){console.warn('PWA indisponível:',error)}});
